<script setup lang="ts">
import { computed,onMounted,onUnmounted,reactive,ref,watch } from "vue";
import { deleteArchive,listArchives,saveArchive,saveArchiveFileLocal,setArchiveDelivered,type LocalArchive } from "@taher/db";
import type { ArchiveInput } from "@taher/core";
import { getArchiveDownloadUrl,uploadArchiveFile,syncPendingArchiveFiles } from "../services/archive-storage";
import { useAuthStore } from "../stores/auth.store";
const auth=useAuthStore();const companyId=computed(()=>auth.activeMembership?.company_id??"");
const canManage=computed(()=>auth.activeRole==="company_admin"||auth.activeRole==="manager");
const canAttach=computed(()=>canManage.value||auth.activeRole==="data_entry");
const rows=ref<LocalArchive[]>([]);const loading=ref(false);const error=ref("");const success=ref("");
const search=ref("");const delivered=ref<"all"|"yes"|"no">("all");const from=ref("");const to=ref("");
const uploading=ref<string|null>(null);const formOpen=ref(false);const saving=ref(false);
const form=reactive<ArchiveInput>({source_table:null,source_id:null,document_type:"وثيقة",counterparty:null,invoice_number:null,document_date:new Date().toISOString().slice(0,10),amount:0,cabinet:null,shelf:null,delivered_to_accountant:false,delivered_at:null,notes:null});
function openCreate(){Object.assign(form,{source_table:null,source_id:null,document_type:"وثيقة",counterparty:null,invoice_number:null,document_date:new Date().toISOString().slice(0,10),amount:0,cabinet:null,shelf:null,delivered_to_accountant:false,delivered_at:null,notes:null});formOpen.value=true;error.value="";}
async function createArchive(){if(!canManage.value||!companyId.value)return;saving.value=true;error.value="";try{await saveArchive(companyId.value,{...form,amount:Number(form.amount)},auth.user?.id??null);formOpen.value=false;success.value="تمت إضافة الوثيقة إلى الأرشيف محلياً.";await load();}catch(e){error.value=e instanceof Error?e.message:"تعذر إنشاء وثيقة الأرشيف.";}finally{saving.value=false;}}
async function load(){if(!companyId.value){rows.value=[];return;}loading.value=true;try{rows.value=await listArchives(companyId.value,{search:search.value,delivered:delivered.value,dateFrom:from.value||undefined,dateTo:to.value||undefined});}catch(e){error.value=e instanceof Error?e.message:"تعذر تحميل الأرشيف.";}finally{loading.value=false;}}
const fmt=(v:number)=>new Intl.NumberFormat("ar-DZ",{style:"currency",currency:auth.activeCompany?.currency_code||"DZD"}).format(v);
async function addFile(row:LocalArchive,event:Event){if(!canAttach.value||!companyId.value)return;const target=event.target as HTMLInputElement;const file=target.files?.[0];if(!file)return;error.value="";success.value="";uploading.value=row.id;try{await saveArchiveFileLocal(companyId.value,row.id,file,file.name);const path=await uploadArchiveFile(companyId.value,row.id,file,file.name);success.value=path?"تم حفظ الملف محلياً ورفعه إلى التخزين السحابي.":"تم حفظ الملف محلياً؛ سيبقى جاهزاً للمزامنة عند توفر الاتصال.";await load();}catch(e){error.value=e instanceof Error?e.message:"تعذر حفظ الملف.";}finally{uploading.value=null;target.value="";}}
async function openFile(row:LocalArchive){try{if(row.file_blob){const url=URL.createObjectURL(row.file_blob);window.open(url,"_blank","noopener");window.setTimeout(()=>URL.revokeObjectURL(url),60000);return;}if(row.storage_path){const url=await getArchiveDownloadUrl(row.storage_path);if(url)window.open(url,"_blank","noopener");else error.value="الملف السحابي غير متاح دون اتصال.";}}catch(e){error.value=e instanceof Error?e.message:"تعذر فتح الملف.";}}
async function toggleDelivered(row:LocalArchive){if(!canManage.value)return;try{await setArchiveDelivered(companyId.value,row.id,!row.delivered_to_accountant);await load();}catch(e){error.value=e instanceof Error?e.message:"تعذر تحديث حالة التسليم.";}}
async function remove(row:LocalArchive){if(!canManage.value||!window.confirm("هل تريد حذف وثيقة الأرشيف؟"))return;try{await deleteArchive(companyId.value,row.id);success.value="تم حذف الوثيقة محلياً.";await load();}catch(e){error.value=e instanceof Error?e.message:"تعذر حذف الوثيقة.";}}
watch([search,delivered,from,to],()=>void load());
function handleOnline(){if(companyId.value)void syncPendingArchiveFiles(companyId.value).then(()=>load()).catch(e=>{error.value=e instanceof Error?e.message:"تعذرت مزامنة ملفات الأرشيف.";});}
onMounted(()=>{void load();handleOnline();window.addEventListener("online",handleOnline);});
onUnmounted(()=>window.removeEventListener("online",handleOnline));
</script>
<template>
<section class="space-y-6"><header class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm font-semibold text-brand-600">المستندات والملفات</p><h1 class="mt-2 text-2xl font-bold text-slate-900">الأرشيف</h1><p class="mt-1 text-sm text-slate-500">حفظ المستندات محلياً ورفعها إلى مساحة الشركة الخاصة عند توفر الإنترنت.</p></div><button v-if="canManage" class="primary-button" @click="openCreate">＋ إضافة وثيقة</button></header>
<div class="grid gap-4 sm:grid-cols-3"><article class="panel p-5"><p class="text-sm text-slate-500">إجمالي الوثائق</p><p class="mt-2 text-2xl font-bold">{{rows.length}}</p></article><article class="panel p-5"><p class="text-sm text-slate-500">تم تسليمها للمحاسب</p><p class="mt-2 text-2xl font-bold text-emerald-700">{{rows.filter(r=>r.delivered_to_accountant).length}}</p></article><article class="panel p-5"><p class="text-sm text-slate-500">بانتظار التسليم</p><p class="mt-2 text-2xl font-bold text-amber-700">{{rows.filter(r=>!r.delivered_to_accountant).length}}</p></article></div>
<div class="panel overflow-hidden"><div class="grid gap-3 border-b border-slate-100 p-4 sm:grid-cols-2 xl:grid-cols-4"><input v-model="search" class="form-input" type="search" placeholder="بحث في نوع الوثيقة أو المورد أو رقمها"><select v-model="delivered" class="form-input"><option value="all">كل الوثائق</option><option value="yes">تم التسليم للمحاسب</option><option value="no">لم يتم التسليم</option></select><input v-model="from" class="form-input" type="date" aria-label="من تاريخ"><input v-model="to" class="form-input" type="date" aria-label="إلى تاريخ"></div>
<p v-if="error" role="alert" class="m-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{{error}}</p><p v-if="success" role="status" class="m-4 rounded-xl bg-emerald-50 p-3 text-sm text-emerald-700">{{success}}</p>
<div class="overflow-x-auto"><table class="w-full min-w-[950px] text-right text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="px-4 py-3">التاريخ</th><th class="px-4 py-3">النوع</th><th class="px-4 py-3">الطرف</th><th class="px-4 py-3">رقم الوثيقة</th><th class="px-4 py-3">المبلغ</th><th class="px-4 py-3">مكان الحفظ</th><th class="px-4 py-3">الملف</th><th class="px-4 py-3">التسليم</th><th class="px-4 py-3">إجراءات</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="r in rows" :key="r.id"><td class="px-4 py-3">{{r.document_date}}</td><td class="px-4 py-3 font-semibold">{{r.document_type}}</td><td class="px-4 py-3">{{r.counterparty||"—"}}</td><td class="px-4 py-3">{{r.invoice_number||"—"}}</td><td class="px-4 py-3">{{fmt(r.amount)}}</td><td class="px-4 py-3">{{[r.cabinet,r.shelf].filter(Boolean).join(" / ")||"—"}}</td><td class="px-4 py-3"><button v-if="r.file_blob||r.storage_path" class="text-brand-700 underline" @click="openFile(r)">فتح {{r.original_file_name||"الملف"}}</button><span v-else class="text-slate-400">لا يوجد ملف</span></td><td class="px-4 py-3"><span :class="r.delivered_to_accountant?'text-emerald-700':'text-amber-700'">{{r.delivered_to_accountant?"تم التسليم":"بانتظار التسليم"}}</span></td><td class="px-4 py-3"><div class="flex items-center gap-2"><label v-if="canAttach" class="secondary-button !px-3 !py-2 cursor-pointer">{{uploading===r.id?"جارٍ الرفع...":"إرفاق"}}
<input class="hidden" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" :disabled="uploading===r.id" @change="addFile(r,$event)"></label><button v-if="canManage" class="secondary-button !px-3 !py-2" @click="toggleDelivered(r)">{{r.delivered_to_accountant?"إلغاء التسليم":"تسليم"}}</button><button v-if="canManage&&!r.source_id" class="text-xs text-red-600" @click="remove(r)">حذف</button></div></td></tr><tr v-if="!loading&&!rows.length"><td colspan="9" class="px-4 py-12 text-center text-slate-400">لا توجد وثائق أرشيف.</td></tr></tbody></table></div></div>
<p class="text-xs leading-6 text-slate-400">الملفات المسموحة: PDF وJPG وPNG وWEBP، بحد أقصى 15 ميغابايت. يحتفظ IndexedDB بنسخة محلية، ويُرفع الملف إلى مساحة Supabase الخاصة عند الاتصال. تتطلب المزامنة الخلفية التلقائية معالجة طابور الملفات في مرحلة المزامنة.</p>
</section>
</template>
